import { CSSProperties, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { memuExtras, st } from 'utils/context-extra';
import { cancelMemorize } from 'utils/network';
import { MemuTaskStatus } from 'utils/types';
import { getInspectData } from 'ui/inspect-panel';
import { currentScope, isMemuActive } from 'memory/utils';

const containerStyle: CSSProperties = {
  position: 'fixed',
  bottom: 16,
  right: 16,
  zIndex: 10000,
  background: 'var(--SmartThemeBlurTintColor, #1a1a2e)',
  border: '1px solid var(--SmartThemeBorderColor, #444)',
  borderRadius: 8,
  padding: '10px 14px',
  display: 'flex',
  alignItems: 'center',
  gap: 10,
  fontSize: 13,
  color: 'var(--SmartThemeBodyColor, #ccc)',
  boxShadow: '0 2px 12px rgba(0,0,0,0.4)',
  minWidth: 180,
};

const barOuter: CSSProperties = {
  flex: 1,
  height: 4,
  background: 'var(--SmartThemeBorderColor, #444)',
  borderRadius: 2,
  minWidth: 60,
  overflow: 'hidden',
};

const cancelBtn: CSSProperties = {
  background: 'none',
  border: 'none',
  color: 'var(--SmartThemeBodyColor, #ccc)',
  cursor: 'pointer',
  fontSize: 14,
  padding: '0 2px',
  opacity: 0.7,
};

function currentTaskKey(): string {
  const info = memuExtras.baseInfo;
  return JSON.stringify([currentScope(), info?.userId, info?.characterId, memuExtras.summary?.summaryTaskId]);
}

export default function MemorizeProgress(): React.JSX.Element | null {
  const [tick, setTick] = useState(0);
  const [cancelling, setCancelling] = useState(false);
  const [refusedTask, setRefusedTask] = useState<string | null>(null);
  const [enabled, setEnabled] = useState(false);
  useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 2000);
    return () => clearInterval(id);
  }, []);

  void tick;
  useEffect(() => {
    let stale = false;
    void isMemuActive().then(value => { if (!stale) setEnabled(value); }).catch(() => { if (!stale) setEnabled(false); });
    return () => { stale = true; };
  }, [tick, currentScope()]);
  const summary = memuExtras.summary;
  const taskKey = currentTaskKey();
  const cancelUnavailable = refusedTask === taskKey;
  const status = summary?.summaryTaskStatus;
  const progress = summary?.progress;
  const active = status === MemuTaskStatus.PENDING || status === MemuTaskStatus.PROCESSING;
  const failed = status === MemuTaskStatus.FAILURE;
  useEffect(() => {
    setCancelling(false);
    if (!active) setRefusedTask(null);
  }, [active, taskKey]);
  const inspect = getInspectData();
  if (!enabled || (st.getContext() as any).chatMetadata?.main_chat) return null;
  if (inspect?.errorCode === 'soul_paused'
    && inspect.userId === memuExtras.baseInfo?.userId
    && inspect.soulId === memuExtras.baseInfo?.characterId) {
    const reason = inspect.turnError || inspect.error || 'Paused. Retry in OpenAlma launcher.';
    return createPortal(<div style={containerStyle}>Last send blocked <span title={`Last request: ${reason}`} aria-label={`Last request: ${reason}`}>!</span></div>, document.body);
  }
  if (!summary) return null;

  if (!active && !failed) {
    return null;
  }

  const progressCurrent = progress?.current ?? 0;
  const progressTotal = progress?.total ?? 0;
  const phase = String(progress?.phase || '').trim().toLowerCase();
  const failedErrorRaw = String(summary.lastError || '').trim();
  const failedError = failedErrorRaw.length > 110
    ? `${failedErrorRaw.slice(0, 110)}...`
    : failedErrorRaw;
  const inConsolidationPhase = !cancelling && (phase === 'consolidation' || phase === 'consolidating');
  const label = cancelling
    ? 'Cancelling...'
    : active && summary.lastError
      ? summary.lastError
    : failed
      ? `Memorize failed.${failedError ? ` ${failedError}` : ''} Retry in OpenAlma launcher.`
    : inConsolidationPhase
      ? 'Finalizing...'
      : status === MemuTaskStatus.PENDING
      ? 'Memorize pending...'
      : phase === 'extracting'
      ? 'Memorizing saved conversations...'
      : progress
      ? `Memorizing (${progressCurrent}/${progressTotal})`
      : 'Memorizing...';
  const pct = progress && progress.total > 0
    ? Math.round((progress.current / progress.total) * 100)
    : 0;

  async function handleCancel() {
    if (cancelling) return;
    const info = memuExtras.baseInfo;
    if (!info) return;
    const { userId, characterId } = info;
    const requestedTask = currentTaskKey();
    let accepted = false;
    try {
      if (!(await isMemuActive()) || requestedTask !== currentTaskKey()) return;
      setCancelling(true);
      const result = await cancelMemorize(userId, characterId);
      if (requestedTask !== currentTaskKey()) return;
      accepted = result.ok === true;
      if (!accepted) setRefusedTask(requestedTask);
    } catch {
      if (requestedTask === currentTaskKey() && memuExtras.summary) {
        memuExtras.summary = { ...memuExtras.summary,
          lastError: 'Cancel could not be confirmed. Checking progress.' };
      }
    } finally {
      if (!accepted && requestedTask === currentTaskKey()) setCancelling(false);
    }
  }

  return createPortal(
    <div style={containerStyle}>
      <span>{label}</span>
      {!cancelling && progress && progress.total > 0 && (
        <div style={barOuter}>
          <div style={{ height: '100%', width: `${pct}%`, background: 'var(--SmartThemeQuoteColor, #6a9fb5)', borderRadius: 2, transition: 'width 0.3s' }} />
        </div>
      )}
      {!cancelling && (
        failed ? (
          <button
            type="button"
            style={cancelBtn}
            onClick={async () => {
              if (!(await isMemuActive())) return;
              memuExtras.summary = undefined;
              void st.saveChat();
            }}
          >
            Dismiss
          </button>
        ) : (
          <button type="button" style={cancelBtn} disabled={cancelUnavailable}
            title={cancelUnavailable ? 'Cannot cancel this run. It will finish normally.' : undefined}
            onClick={() => void handleCancel()}>
            Cancel
          </button>
        )
      )}
    </div>,
    document.body,
  );
}
